// mine_pad.ino — ESP32-S3: клавиатура 4x4 + джойстик HW-504 = управление Minecraft
// BOOT — зелёная матрица
#include "USB.h"
#include "USBHIDKeyboard.h"
#include "USBHIDMouse.h"
#include <Keypad.h>

USBHIDKeyboard Keyboard;
USBHIDMouse Mouse;

// ===== Клавиатура 4x4 =====
const byte ROWS = 4;
const byte COLS = 4;
char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins[ROWS] = {10, 11, 12, 13};
byte colPins[COLS] = {7, 6, 5, 4};
Keypad keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

// ===== Джойстик =====
const int VRX_PIN = 15;
const int VRY_PIN = 17;
const int SW_PIN  = 16;

const bool  INVERT_X    = false;  // камера едет не туда по X — поменяй на true
const bool  INVERT_Y    = false;  // камера едет не туда по Y — поменяй на true
const int   JOY_DEADZONE = 80;    // мёртвая зона (0-4095)
const float JOY_SPEED    = 14.0;  // скорость камеры: больше = быстрее

int centerX = 2048, centerY = 2048;

// ===== Состояние удержаний =====
bool wDown = false, sDown = false, aDown = false, dDown = false;
bool spaceDown = false, shiftDown = false, tabDown = false;
bool lmbKeypad = false, lmbJoy = false, rmbDown = false;

void tapKey(char c) {
  Keyboard.press(c);
  delay(40);
  Keyboard.release(c);
}

void matrixLaunch() {
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press(' '); // Win+Space — сброс раскладки
  delay(60);  Keyboard.releaseAll(); delay(400);
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');
  delay(60);  Keyboard.releaseAll(); delay(600);
  Keyboard.print("cmd /k \"color 2&for /l %i in (1,0,2) do @dir /s\"");
  Keyboard.press(KEY_RETURN); delay(40); Keyboard.releaseAll();
  delay(1500);
  Keyboard.press(KEY_F11); delay(50); Keyboard.releaseAll();
}

void keypadEvent(KeypadEvent key) {
  KeypadState st = keypad.getState();

  if (st == PRESSED) {
    switch (key) {
      // ходьба — удержание
      case '2': if (!wDown)   { Keyboard.press('w');   wDown = true; }   break;
      case '8': if (!sDown)   { Keyboard.press('s');   sDown = true; }   break;
      case '4': if (!aDown)   { Keyboard.press('a');   aDown = true; }   break;
      case '6': if (!dDown)   { Keyboard.press('d');   dDown = true; }   break;
      // прыжок / присед — удержание
      case '5': if (!spaceDown) { Keyboard.press(KEY_SPACE);      spaceDown = true; } break;
      case '1': if (!shiftDown) { Keyboard.press(KEY_LEFT_SHIFT); shiftDown = true; } break;
      // ломать / ставить — удержание
      case '7': if (!lmbKeypad) { Mouse.press(MOUSE_LEFT);  lmbKeypad = true; } break;
      case '9': if (!rmbDown)   { Mouse.press(MOUSE_RIGHT); rmbDown   = true; } break;
      // тапы
      case '3': tapKey('e');                  break; // инвентарь
      case '0': tapKey(KEY_ESC);              break; // меню
      case 'A': tapKey(KEY_F5);               break; // вид от 3-го лица
      // список игроков — удержание
      case 'B': if (!tabDown) { Keyboard.press(KEY_TAB); tabDown = true; } break;
      // слоты
      case 'C': tapKey('1'); break;
      case 'D': tapKey('2'); break;
      case '*': tapKey('3'); break;
      case '#': tapKey('4'); break;
    }
  }

  if (st == RELEASED) {
    switch (key) {
      case '2': if (wDown)     { Keyboard.release('w');           wDown = false; }     break;
      case '8': if (sDown)     { Keyboard.release('s');           sDown = false; }     break;
      case '4': if (aDown)     { Keyboard.release('a');           aDown = false; }     break;
      case '6': if (dDown)     { Keyboard.release('d');           dDown = false; }     break;
      case '5': if (spaceDown) { Keyboard.release(KEY_SPACE);     spaceDown = false; } break;
      case '1': if (shiftDown) { Keyboard.release(KEY_LEFT_SHIFT);shiftDown = false; } break;
      case '7': if (lmbKeypad) { Mouse.release(MOUSE_LEFT);       lmbKeypad = false; } break;
      case '9': if (rmbDown)   { Mouse.release(MOUSE_RIGHT);      rmbDown = false; }   break;
      case 'B': if (tabDown)   { Keyboard.release(KEY_TAB);       tabDown = false; }   break;
    }
  }
}

void setup() {
  pinMode(0, INPUT_PULLUP);   // BOOT — матрица
  pinMode(SW_PIN, INPUT_PULLUP); // SW джойстика

  Keyboard.begin();
  Mouse.begin();
  USB.begin();
  delay(3000); // ждём, пока ОС опознает устройство

  analogReadResolution(12);

  // калибровка центра стика — НЕ трогать стик в этот момент!
  long sx = 0, sy = 0;
  for (int i = 0; i < 64; i++) {
    sx += analogRead(VRX_PIN);
    sy += analogRead(VRY_PIN);
  }
  centerX = sx / 64;
  centerY = sy / 64;

  keypad.addEventListener(keypadEvent);
  keypad.setHoldTime(20);

  // жмём BOOT — запускаем матрицу
  while (digitalRead(0) == HIGH) {
    keypad.getKeys();
    delay(10);
  }
  delay(50);
  matrixLaunch();
}

void loop() {
  keypad.getKeys();

  // ---- SW джойстика: ломать ----
  bool sw = (digitalRead(SW_PIN) == LOW);
  if (sw && !lmbJoy)        { Mouse.press(MOUSE_LEFT);   lmbJoy = true; }
  if (!sw && lmbJoy)        { Mouse.release(MOUSE_LEFT); lmbJoy = false; }

  // ---- камера ----
  int x = analogRead(VRX_PIN) - centerX;
  int y = analogRead(VRY_PIN) - centerY;

  int dx = 0, dy = 0;
  if (abs(x) > JOY_DEADZONE) {
    dx = (int)((float)x / 2048.0 * JOY_SPEED);
    if (INVERT_X) dx = -dx;
  }
  if (abs(y) > JOY_DEADZONE) {
    dy = (int)((float)y / 2048.0 * JOY_SPEED);
    if (INVERT_Y) dy = -dy;
  }
  dx = constrain(dx, -127, 127);
  dy = constrain(dy, -127, 127);
  if (dx != 0 || dy != 0) Mouse.move(dx, dy);

  delay(5);
}
